package com.omegaapi.huesort

import kotlin.random.Random

/**
 * Pure, deterministic game rules for Hue Sort.
 *
 * No Android or ads code lives here so the rules can be unit tested on the JVM.
 * A level is generated by starting from a solved board and applying random inverse
 * pours. Every inverse step is the reverse of a legal pour, so the scramble is
 * always solvable.
 */
data class GameState(
    val level: Int,
    val tubes: List<List<Int>>,
    val capacity: Int,
    val colorCount: Int,
    val moves: Int = 0,
    val seed: Long = DEFAULT_SEED,
    val bonusTubes: Int = 0
) {
    companion object {
        const val DEFAULT_SEED = 20261123L
    }
}

data class PourResult(
    val state: GameState,
    val moved: Int,
    val valid: Boolean
)

object GameEngine {

    const val MAX_BONUS_TUBES = 3
    private const val SCRAMBLE_MOVES = 240

    /** Number of same-colour segments that can leave the top of a tube. */
    private fun topRun(tube: List<Int>): Int {
        if (tube.isEmpty()) return 0
        val color = tube.last()
        var count = 0
        for (index in tube.indices.reversed()) {
            if (tube[index] != color) break
            count++
        }
        return count
    }

    /** Returns how many segments would move, or 0 when the pour is illegal. */
    fun canPour(state: GameState, from: Int, to: Int): Int {
        if (from == to) return 0
        if (from !in state.tubes.indices || to !in state.tubes.indices) return 0

        val source = state.tubes[from]
        val destination = state.tubes[to]
        if (source.isEmpty()) return 0
        if (destination.size >= state.capacity) return 0
        if (destination.isNotEmpty() && destination.last() != source.last()) return 0

        return minOf(topRun(source), state.capacity - destination.size)
    }

    fun pour(state: GameState, from: Int, to: Int): PourResult {
        val moved = canPour(state, from, to)
        if (moved == 0) return PourResult(state, 0, false)

        val nextTubes = state.tubes.toMutableList()
        val source = nextTubes[from].toMutableList()
        val destination = nextTubes[to].toMutableList()

        repeat(moved) {
            destination.add(source.removeAt(source.lastIndex))
        }

        nextTubes[from] = source
        nextTubes[to] = destination

        return PourResult(
            state = state.copy(tubes = nextTubes, moves = state.moves + 1),
            moved = moved,
            valid = true
        )
    }

    fun isSolved(state: GameState): Boolean {
        val used = state.tubes.filter { it.isNotEmpty() }
        if (used.size != state.colorCount) return false
        return used.all { tube ->
            tube.size == state.capacity && tube.all { color -> color == tube.first() }
        }
    }

    fun legalMoves(state: GameState): List<Pair<Int, Int>> = buildList {
        for (from in state.tubes.indices) {
            for (to in state.tubes.indices) {
                if (canPour(state, from, to) > 0) {
                    add(from to to)
                }
            }
        }
    }

    /**
     * Inverse of a legal pour. Moving `amount` top segments from donor to receiver
     * is reversible exactly when the donor keeps a same-colour top or becomes empty.
     * Scrambling with these moves guarantees a solvable board.
     */
    private fun reverseCandidates(state: GameState): List<Triple<Int, Int, Int>> = buildList {
        for (donor in state.tubes.indices) {
            val tube = state.tubes[donor]
            if (tube.isEmpty()) continue
            val run = topRun(tube)

            for (receiver in state.tubes.indices) {
                if (receiver == donor) continue
                val space = state.capacity - state.tubes[receiver].size
                if (space <= 0) continue

                for (amount in 1..minOf(run, space)) {
                    if (amount < run || amount == tube.size) {
                        add(Triple(donor, receiver, amount))
                    }
                }
            }
        }
    }

    private fun applyReverse(
        state: GameState,
        donor: Int,
        receiver: Int,
        amount: Int
    ): GameState {
        val nextTubes = state.tubes.toMutableList()
        val donorTube = nextTubes[donor].toMutableList()
        val moved = MutableList(amount) { donorTube.removeAt(donorTube.lastIndex) }
        val receiverTube = nextTubes[receiver].toMutableList()
        receiverTube.addAll(moved)

        nextTubes[donor] = donorTube
        nextTubes[receiver] = receiverTube
        return state.copy(tubes = nextTubes)
    }

    /** Deterministic hint that prefers consolidating colours over filling empty tubes. */
    fun hint(state: GameState): Pair<Int, Int>? =
        legalMoves(state)
            .map { move -> move to scoreMove(state, move.first, move.second) }
            .maxByOrNull { it.second }
            ?.first

    private fun scoreMove(state: GameState, from: Int, to: Int): Int {
        val moved = canPour(state, from, to)
        val source = state.tubes[from]
        val destination = state.tubes[to]
        var score = moved * 10

        if (destination.isNotEmpty()) score += 60
        if (moved == topRun(source)) score += 25
        if (source.size == moved && source.all { it == source.first() }) score -= 40
        if (destination.isEmpty() && moved < topRun(source)) score -= 15

        return score
    }

    /** Applies extra legal pours to the current board, keeping it solvable. */
    fun shuffle(state: GameState, seed: Long): GameState {
        val random = Random(seed)
        var current = state
        var last: Pair<Int, Int>? = null

        repeat(60) {
            val forbidden = last?.let { it.second to it.first }
            val candidates = reverseCandidates(current).filter { move ->
                forbidden == null || (move.first to move.second) != forbidden
            }
            if (candidates.isEmpty()) {
                last = null
                return@repeat
            }
            val move = candidates[random.nextInt(candidates.size)]
            current = applyReverse(current, move.first, move.second, move.third)
                .copy(moves = state.moves)
            last = move.first to move.second
        }

        if (isSolved(current)) return shuffle(state, seed + 1)
        return current.copy(moves = state.moves)
    }

    /** Rewarded extra tube. Capped so the board cannot become trivial. */
    fun addTube(state: GameState): GameState {
        if (state.bonusTubes >= MAX_BONUS_TUBES) return state
        return state.copy(
            tubes = state.tubes + listOf(emptyList<Int>()),
            bonusTubes = state.bonusTubes + 1
        )
    }

    fun generateLevel(level: Int, seed: Long = GameState.DEFAULT_SEED): GameState {
        val safeLevel = level.coerceAtLeast(1)
        val colorCount = (3 + (safeLevel - 1) / 3).coerceAtMost(9)
        val capacity = if (safeLevel >= 18) 5 else 4
        val emptyTubes = 2
        val tubeCount = colorCount + emptyTubes

        val solved = buildList {
            repeat(colorCount) { color -> add(List(capacity) { color }) }
            repeat(emptyTubes) { add(emptyList<Int>()) }
        }

        var state = GameState(
            level = safeLevel,
            tubes = solved,
            capacity = capacity,
            colorCount = colorCount,
            seed = seed
        )

        val random = Random(seed + safeLevel * 7919L)
        var last: Pair<Int, Int>? = null

        repeat(SCRAMBLE_MOVES) {
            val forbidden = last?.let { it.second to it.first }
            val candidates = reverseCandidates(state).filter { move ->
                forbidden == null || (move.first to move.second) != forbidden
            }
            if (candidates.isEmpty()) {
                last = null
                return@repeat
            }
            val move = candidates[random.nextInt(candidates.size)]
            state = applyReverse(state, move.first, move.second, move.third)
                .copy(moves = 0)
            last = move.first to move.second
        }

        if (isSolved(state) || state.tubes.size != tubeCount) {
            return generateLevel(safeLevel, seed + 1)
        }

        return state.copy(moves = 0)
    }

    /** Stable representation used by tests and future save support. */
    fun signature(state: GameState): String =
        state.tubes.joinToString("|") { tube -> tube.joinToString(",") }

    fun colorCounts(state: GameState): Map<Int, Int> =
        state.tubes.flatten().groupingBy { it }.eachCount()
}
